const r = document.getElementById('link-report');
const d = document.getElementById('link-docs');
const p = document.getElementById('link-aria');
const im = document.getElementById('link-img');
if (!r || !d || !p || !im) return false;

const isEnabled = r.classList.contains('ai4a11y-adapted');
if (!isEnabled) {
  return !r.hasAttribute('aria-label') &&
         r.textContent === 'click here' &&
         d.textContent === 'read more' &&
         p.getAttribute('aria-label') === 'here' &&
         r.dataset.ai4a11yProcessed === undefined;
}

const expected = 'Download 2026 Annual Performance Report';
return r.getAttribute('aria-label') === expected &&
       r.textContent === 'click here' &&
       d.getAttribute('aria-label') === expected &&
       d.textContent === 'read more' &&
       p.getAttribute('aria-label') === expected &&
       im.getAttribute('aria-label') === expected &&
       r.classList.contains('ai4a11y-adapted') &&
       r.dataset.ai4a11yProcessed === 'done';

const links = [
  document.getElementById('link-report'),
  document.getElementById('link-docs'),
  document.getElementById('link-aria'),
  document.getElementById('link-img')
];
if (links.some(l => !l)) return false;

for (const link of links) {
  if (link.tabIndex < 0) return false;
  link.scrollIntoView({ block: "center" });
  link.focus();
  if (document.activeElement !== link) return false;

  const style = window.getComputedStyle(link);
  const outlineWidth = parseFloat(style.outlineWidth) || 0;
  if (outlineWidth < 2) return false;

  // A link that wraps has two boxes; the middle of its bounding box can be the text between them.
  const rect = link.getClientRects()[0] || link.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return false;

  const cx = rect.left + rect.width / 2;
  const cy = rect.top + rect.height / 2;
  const hit = document.elementFromPoint(cx, cy);
  if (hit !== link && !link.contains(hit)) return false;

  link.blur();
}
return true;

const goodLink = document.getElementById('link-descriptive');
const navNews = document.getElementById('nav-news');
const navArchive = document.getElementById('nav-archive');
const emailInput = document.getElementById('sub-email');
const subButton = document.getElementById('sub-button');
const h1 = document.querySelector('h1');

if (!goodLink || !navNews || !navArchive || !emailInput || !subButton || !h1) return false;

if (goodLink.hasAttribute('aria-label')) return false;
if (goodLink.classList.contains('ai4a11y-adapted')) return false;
if (navNews.hasAttribute('aria-label')) return false;
if (navArchive.hasAttribute('aria-label')) return false;

if (emailInput.value !== '') return false;
if (subButton.disabled) return false;
return h1.textContent === 'Tech Trends Weekly';

